/// Appearance mode. The high-contrast modes are chosen by the app or the system preference.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Mode {
    Light,
    Dark,
    LightHc,
    DarkHc,
}

impl Mode {
    pub const ALL: [Mode; 4] = [Mode::Light, Mode::Dark, Mode::LightHc, Mode::DarkHc];

    /// The token name of the mode, as used by the other NDL adapters.
    pub const fn name(self) -> &'static str {
        match self {
            Mode::Light => "light",
            Mode::Dark => "dark",
            Mode::LightHc => "light-hc",
            Mode::DarkHc => "dark-hc",
        }
    }

    pub const fn is_dark(self) -> bool {
        matches!(self, Mode::Dark | Mode::DarkHc)
    }

    pub const fn is_high_contrast(self) -> bool {
        matches!(self, Mode::LightHc | Mode::DarkHc)
    }

    pub const fn palette(self) -> &'static Palette {
        match self {
            Mode::Light => &LIGHT,
            Mode::Dark => &DARK,
            Mode::LightHc => &LIGHT_HC,
            Mode::DarkHc => &DARK_HC,
        }
    }
}

